def render_blocks_bbcode(blocks):
    out=""
    for b in blocks:
        if b[0]=='Header':
            _, level, inlines, ident, classes = b
            def bb(lst):
                s=""
                for typ,*rest in lst:
                    if typ=='Str': s+=rest[0]
                    elif typ=='Space': s+=' '
                    elif typ=='Emph': s+='[i]'+bb(rest[0])+'[/i]'
                    elif typ=='Strong': s+='[b]'+bb(rest[0])+'[/b]'
                    elif typ=='Code': s+='[code]'+rest[0]+'[/code]'
                    elif typ=='Link': s+=f'[url={rest[1]}]{bb(rest[0])}[/url]'
                    else: s+=''
                return s
            content=bb(inlines)
            # header as [u][b]Hi[/b][/u]? For h1, observed "[u][b]Hi[/b][/u]". For h2? Probably different? Assume same for all?
            out+=f'[u][b]{content}[/b][/u]\n\n'
        elif b[0]=='Para':
            def bb2(lst):
                s=""
                for typ,*rest in lst:
                    if typ=='Str': s+=rest[0]
                    elif typ=='Space': s+=' '
                    elif typ=='Emph': s+='[i]'+bb2(rest[0])+'[/i]'
                    elif typ=='Strong': s+='[b]'+bb2(rest[0])+'[/b]'
                    elif typ=='Code': s+='[code]'+rest[0]+'[/code]'
                    elif typ=='Link': s+=f'[url={rest[1]}]{bb2(rest[0])}[/url]'
                    else: s+=''
                return s
            out+=bb2(b[1])+'\n\n'
        elif b[0]=='BulletList':
            out+='[list]\n'
            for item in b[1]:
                out+='[*]'+inline_plain_text(item)+'\n'
            out+='[/list]\n\n'
        elif b[0]=='OrderedList':
            _, items, start = b
            out+='[list=1]\n'
            for item in items:
                out+='[*]'+inline_plain_text(item)+'\n'
            out+='[/list]\n\n'
        elif b[0]=='CodeBlock':
            _, lang, text = b
            out+='[code]\n'+text+'\n[/code]\n\n'
        elif b[0]=='HRule':
            out+='[hr]\n\n'
        else:
            pass
    return out

