    # Fix jats combining: wrap header+following in sec
    new_out=""
    i=0
    while i<len(blocks):
        b=blocks[i]
        if b[0]=='Header':
            _, level, inlines, ident, classes = b
            title=html_escape(inline_plain_text(inlines))
            new_out+=f'<sec id="{ident}">\n  <title>{title}</title>\n'
            i+=1
            while i<len(blocks) and blocks[i][0]!='Header':
                nb=blocks[i]
                if nb[0]=='Para':
                    s=""
                    for typ,*rest in nb[1]:
                        if typ=='Str': s+=html_escape(rest[0])
                        elif typ=='Space': s+=' '
                        elif typ=='Emph': s+='<italic>'+html_escape(inline_plain_text(rest[0]))+'</italic>'
                        elif typ=='Strong': s+='<bold>'+html_escape(inline_plain_text(rest[0]))+'</bold>'
                        elif typ=='Code': s+='<code>'+html_escape(rest[0])+'</code>'
                        else: s+=''
                    new_out+=f'  <p>{s}</p>\n'
                i+=1
            new_out+='</sec>\n'
        else:
            if b[0]=='Para':
                s=""
                for typ,*rest in b[1]:
                    if typ=='Str': s+=html_escape(rest[0])
                    elif typ=='Space': s+=' '
                    elif typ=='Emph': s+='<italic>'+html_escape(inline_plain_text(rest[0]))+'</italic>'
                    else: s+=''
                new_out+=f'<p>{s}</p>\n'
            i+=1
    return new_out if new_out else out

