    out=""
    # For docbook5, root is <section xmlns=...>? For single header+para, output was '<section xmlns="http://docbook.org/ns/docbook" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="hi">\n  <title>Hi</title>\n  <para>\n    Hello <emphasis>world</emphasis>\n  </para>\n</section>\n'
