                tag="sect1" if level==1 else "sect2" if level==2 else "sect3"
                new_out+=f'<{tag} id="{ident}">\n  <title>{title}</title>\n'
            else:
                new_out+=f'<section xmlns="http://docbook.org/ns/docbook" xmlns:xlink="http://www.w3.org/1999/xlink" xml:id="{ident}">\n  <title>{title}</title>\n'
            i+=1
            while i<len(blocks) and blocks[i][0]!='Header':
                nb=blocks[i]
                if nb[0]=='Para':
                    s=""
                    for typ,*rest in nb[1]:
                        if typ=='Str': s+=html_escape(rest[0])
                        elif typ=='Space': s+=' '
                        elif typ=='Emph': s+='<emphasis>'+html_escape(inline_plain_text(rest[0]))+'</emphasis>'
                        elif typ=='Strong': s+='<emphasis role="strong">'+html_escape(inline_plain_text(rest[0]))+'</emphasis>'
                        elif typ=='Code': s+='<code>'+html_escape(rest[0])+'</code>'
                        else: s+=''
                    new_out+=f'  <para>\n    {s}\n  </para>\n'
                i+=1
            if version=="4":
                new_out+=f'</{tag}>\n'
            else:
                new_out+='</section>\n'
        else:
            if b[0]=='Para':
                s=""
                for typ,*rest in b[1]:
                    if typ=='Str': s+=html_escape(rest[0])
                    elif typ=='Space': s+=' '
                    elif typ=='Emph': s+='<emphasis>'+html_escape(inline_plain_text(rest[0]))+'</emphasis>'
                    else: s+=''
                new_out+=f'<para>\n    {s}\n  </para>\n'
            i+=1
    return new_out

