def render_blocks_muse(blocks):
    out=""
    for b in blocks:
        if b[0]=='Header':
            _, level, inlines, ident, classes = b
            out+='*'*level+' '+inline_plain_text(inlines)+'\n\n'
        elif b[0]=='Para':
            s=""
            for typ,*rest in b[1]:
                if typ=='Str': s+=rest[0]
                elif typ=='Space': s+=' '
                elif typ=='Emph': s+='*'+inline_plain_text(rest[0])+'*'
                elif typ=='Strong': s+='**'+inline_plain_text(rest[0])+'**'
                elif typ=='Code': s+='`'+rest[0]+'`'
                elif typ=='Link': s+=f'[[{rest[1]}][{inline_plain_text(rest[0])}]]'
                else: s+=''
            out+=s+'\n\n'
        elif b[0]=='BulletList':
            for item in b[1]:
                out+=' - '+inline_plain_text(item)+'\n'
            out+='\n'
        elif b[0]=='HRule':
            out+='----\n\n'
        else:
            out+=''
    return out

