import subprocess as sp
def o(args, inp):
    p=sp.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return p.stdout.decode(), p.stderr.decode()
def c(args, inp):
    p=sp.run(["python3","pandoc.py"]+args, input=inp.encode(), capture_output=True)
    return p.stdout.decode(), p.stderr.decode()

for inp,args in [
    ("# Hi\n", ["-f","markdown","-t","html","-s"]),
    ("# Hi\n", ["-f","markdown","-t","html","-s","-M","title=MyTitle"]),
    ("---\ntitle: T\nauthor: A\ndate: D\n---\n\n# Hi\n", ["-f","markdown","-t","html","-s"]),
]:
    co,ce=o(args,inp)
    cc,cee=c(args,inp)
    print(f"INP={repr(inp[:30])} MATCH={co==cc}")
    if co!=cc:
        print("ORIG len",len(co),"CLONE len",len(cc))
        # find first diff
        for i,(a,b) in enumerate(zip(co,cc)):
            if a!=b:
                print(f"diff at {i}: orig={repr(co[i-50:i+50])} clone={repr(cc[i-50:i+50])}")
                break
        if len(co)!=len(cc):
            print(f"len diff orig {len(co)} clone {len(cc)}")
            print(repr(co[-500:]))
            print("---clone---")
            print(repr(cc[-500:]))
