for fmt in outfmts:
    if fmt in ("pdf","docx","odt","epub","epub2","epub3","pptx","ipynb","chunkedhtml","opendocument"):
        continue
    co,ce,rc=o(["-f","markdown","-t",fmt], "# Hi\n\nHello *world*\n")
    cc,cee,crc=c(["-f","markdown","-t",fmt], "# Hi\n\nHello *world*\n")
    if co!=cc or ce!=cee or rc!=crc:
        print(f"DIFF {fmt}")
        if co!=cc:
            print(f"  out orig={repr(co[:500])} clone={repr(cc[:500])}")
    else:
        print(f"OK {fmt}")
